mapper.select:
/* common.mpvo.selectMasterMpVoVocCompanyPop */ SELECT Y.BUYER, (SELECT COM_NAME_LOC FROM V_VOC_ICOMCMPY WHERE COM_CODE=Y.BUYER AND SYS_TYPE=Y.SYS_TYPE AND BUSINESS_COND LIKE '%B%') AS BUYER_NAME, Y.CNT, Y.SYS_TYPE FROM ( SELECT X.BUYER AS BUYER, COUNT(*) AS CNT, X.SYS_TYPE AS SYS_TYPE FROM ( SELECT A.BUYER AS BUYER, A.VC_NO AS VC_NO, A.SYS_TYPE AS SYS_TYPE FROM KEPAVCDT A
, ( SELECT CODE FROM ICOMCOD1 WHERE TYPE = 'VC01' AND TEXT3 = #{st_claim_kind} ) B
WHERE TO_CHAR(A.CD_DATE,'YYYYMMDD') BETWEEN #{st_fromDate} AND #{st_toDate}
AND A.CLAIM_TYPE = B.CODE
AND A.SYS_TYPE = #{st_sys_type}
GROUP BY A.BUYER, A.VC_NO, A.SYS_TYPE ) X GROUP BY X.BUYER, X.SYS_TYPE ) Y ORDER BY 2

/* common.mpvo.masterMpVoVocAgntcmpyPop */ SELECT Y.AGENT, (SELECT COM_NAME_LOC FROM V_VOC_ICOMCMPY WHERE COM_CODE=Y.AGENT AND SYS_TYPE=Y.SYS_TYPE AND BUSINESS_COND LIKE '%S%') AS AGENT_NAME, Y.CNT, Y.SYS_TYPE FROM ( SELECT X.AGENT AS AGENT, COUNT(*) AS CNT, X.SYS_TYPE AS SYS_TYPE FROM ( SELECT A.IMPUTE_AGENT AS AGENT, A.VC_NO AS VC_NO, A.SYS_TYPE AS SYS_TYPE, A.BUYER AS BUYER FROM KEPAVCDT A
, ( SELECT CODE FROM ICOMCOD1 WHERE TYPE = 'VC01' AND TEXT3 = #{st_claim_kind} ) B
WHERE A.IMPUTE_TYPE IN ('SS', 'MS') AND TO_CHAR(A.CD_DATE,'YYYYMMDD') BETWEEN #{st_fromDate} AND #{st_toDate}
AND A.CLAIM_TYPE = B.CODE
AND A.SYS_TYPE = #{st_sys_type}
GROUP BY A.IMPUTE_AGENT, A.VC_NO, A.SYS_TYPE, A.BUYER ) X GROUP BY X.AGENT, X.SYS_TYPE ) Y ORDER BY 2
